<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= esc($title) ?> | Student Records</title><style>body{font-family:system-ui;margin:0;background:#f4f7fa;color:#172635}header{background:#173a5e;color:#fff;padding:14px 5%;display:flex;gap:20px;align-items:center;justify-content:space-between}nav{display:flex;gap:14px;align-items:center;flex-wrap:wrap}nav a{color:#fff}main{max-width:1100px;margin:28px auto;padding:0 18px}table{width:100%;border-collapse:collapse;background:#fff}th,td{padding:10px;border-bottom:1px solid #dbe3ea;text-align:left}form{display:grid;gap:12px;max-width:680px}textarea,input,select{padding:8px;width:100%;box-sizing:border-box}.filters{max-width:none;grid-template-columns:2fr 1fr auto;align-items:end;margin-bottom:18px}button,.button{background:#166a72;color:#fff;border:0;padding:9px 13px;border-radius:4px;text-decoration:none;cursor:pointer}.alert{padding:10px;border-radius:4px}.error{background:#ffe5e5}.success{background:#e2f5e8}.table-wrap{overflow:auto}@media(max-width:650px){.filters{grid-template-columns:1fr}header{align-items:flex-start;flex-direction:column}}</style></head><body><header><strong>Student Records Admin</strong><nav><a href="<?= site_url('admin/dashboard') ?>">Dashboard</a><a href="<?= site_url('admin/students') ?>">Students</a><a href="<?= site_url('admin/verifications') ?>">Verifications</a><a href="<?= site_url('admin/verification-requests') ?>">Requests</a><form method="post" action="<?= site_url('admin/logout') ?>"><?= csrf_field() ?><button>Log out</button></form></nav></header><main><h1><?= esc($title) ?></h1><?php if($error=session()->getFlashdata('error')):?><p class="alert error" role="alert"><?= esc($error) ?></p><?php endif ?><?php if($success=session()->getFlashdata('success')):?><p class="alert success" role="status"><?= esc($success) ?></p><?php endif ?><?= $this->renderSection('content') ?></main></body></html>
